CREATE VIEW "public"."project_performance" AS (select "project_id", coalesce(sum(case when "kind" = 'sales' then "total" else 0 end), 0) as "sales", coalesce(sum(case when "kind" = 'cost' then "total" else 0 end), 0) as "cost", coalesce(sum(case when "kind" = 'sales' then "total" else -"total" end), 0) as "margin", count(distinct "location_id") as "site_count" from "daily_transactions" group by "daily_transactions"."project_id");